// h in 0..t, v in 0..t-1

// When we extend to y3 at position i+1:
// y3 != y2
// Check if y1, y2, y3 form a hump or valley at y2:
//   Hump: y1 < y2 > y3
//   Valley: y1 > y2 < y3
// Update h and v accordingly

long long dp[21][5][5][11][11];

