            for (int y2 = 1; y2 <= 4; y2++) {
                if (y1 == y2) continue;
                for (int h = 0; h <= t; h++) {
                    for (int v = 0; v <= t; v++) {
                        if (dp[i-1][y1][y2][h][v] == 0) continue;

                        for (int y3 = 1; y3 <= 4; y3++) {
                            if (y3 == y2) continue;

                            int new_h = h;
                            int new_v = v;

                            // Check if y2 is a hump or valley
                            // Hump: y1 < y2 > y3
                            if (y1 < y2 && y2 > y3) {
                                new_h = h + 1;
                            }
                            // Valley: y1 > y2 < y3
                            else if (y1 > y2 && y2 < y3) {
                                new_v = v + 1;
                            }

                            if (new_h <= t && new_v <= t) {
                                dp[i][y2][y3][new_h][new_v] += dp[i-1][y1][y2][h][v];
                            }
                        }
                    }
                }
            }
        }
    }

