    long long result = 0;
    for (int y1 = 1; y1 <= 4; y1++) {
        for (int y2 = 1; y2 <= 4; y2++) {
            if (y1 == y2) continue;
            result += dp[n][y1][y2][t][t-1];
        }
    }

    cout << result << endl;

    return 0;
