    // valleys: 0..t (11)

    // Total: 21*5*5*11*11 = 63355, which is fine

    long long memo[21][5][5][11][11];
    for (int i = 0; i < 21; i++)
        for (int j = 0; j < 5; j++)
            for (int k = 0; k < 5; k++)
                for (int l = 0; l < 11; l++)
                    for (int m = 0; m < 11; m++)
                        memo[i][j][k][l][m] = -1;

    function<long long(int, int, int, int, int)> dfs = [&](int pos, int last, int second_last, int humps, int valleys) -> long long {
        if (pos == n) {
            if (humps == t && valleys == t - 1)
                return 1;
            return 0;
        }

        if (memo[pos][last][second_last][humps][valleys] != -1)
            return memo[pos][last][second_last][humps][valleys];

        long long res = 0;
        for (int y = 1; y <= 4; y++) {
            if (pos >= 1 && y == last) continue;

            int new_humps = humps;
            int new_valleys = valleys;

            if (pos >= 2) {
                // Check if last is a hump or valley
                if (second_last < last && last > y) {
                    new_humps++;
                } else if (second_last > last && last < y) {
                    new_valleys++;
                }
            }

            if (new_humps <= t && new_valleys <= t - 1) {
                int new_last = y;
                int new_second_last = (pos >= 1) ? last : 0;
                res += dfs(pos + 1, new_last, new_second_last, new_humps, new_valleys);
            }
        }

        memo[pos][last][second_last][humps][valleys] = res;
        return res;
    };

    // Start: pos=0, last=0, second_last=0, humps=0, valleys=0
    cout << dfs(0, 0, 0, 0, 0) << endl;

    return 0;
